#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$o" ] || { echo "not found: stdout should be empty: $o"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$o" ] || { echo "usage: stdout should be empty: $o"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null
! grep -q '^aoi.2026-01-05.09:00' "$t2" || { echo "aoi booking still there"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "other room's booking removed"; fail=1; }
rm -f "$t" "$t2"; exit $fail

