#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); c=$?
[ $c = 1 ] || { echo "not found should exit 1, got $c"; fail=1; }
[ -z "$o" ] || { echo "not found should print nothing to stdout: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$e" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $e"; fail=1; }
o=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); c=$?
[ $c = 2 ] || { echo "usage should exit 2, got $c"; fail=1; }
[ -z "$o" ] || { echo "usage should print nothing to stdout: $o"; fail=1; }
e=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$e" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message on stderr: $e"; fail=1; }
rm -f "$t"
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel aoi failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "same date and start in another room was removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t2" || { echo "aoi booking still there"; fail=1; }
rm -f "$t2"; exit $fail

