#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00.14:00.y' "$t" || { echo "other booking (kaede) lost"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found: stdout should be empty: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found: stderr: $err"; fail=1; }
out=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage: stdout should be empty: $out"; fail=1; }
err=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage: stderr: $err"; fail=1; }
rm -f "$t"

t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel (same slot, other room) failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "same slot: cancel output: $out"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.y' "$t" || { echo "same slot: kaede booking removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "same slot: aoi booking still there"; fail=1; }
rm -f "$t"; exit $fail

